
const toast=document.querySelector('.toast');let timer;function tell(text){toast.textContent=text;clearTimeout(timer);timer=setTimeout(()=>toast.textContent='',4500)}
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{const k=b.dataset.demo;document.getElementById(k+'-name').textContent=k==='bom'?'demo_bom.xlsx · 合成示例':'demo_material.xlsx · 合成示例';b.textContent='示例已载入';if(k==='bom'){document.getElementById('sheet').disabled=false;document.getElementById('sheet').innerHTML='<option>Sheet1 · 合成示例</option><option>Sheet2 · 合成示例</option>';document.getElementById('generate').disabled=false}tell('仅载入原型示例，没有读取或上传真实文件。')});
const generate=document.getElementById('generate');if(generate)generate.onclick=()=>{generate.disabled=true;generate.textContent='正在演示转换状态…';setTimeout(()=>{generate.disabled=false;generate.textContent='重新演示转换状态 ↗';document.getElementById('result').textContent='状态演示结束。真实产品在此下载 Excel；本原型未转换或生成文件。'},700)};
document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>tell(b.dataset.message));
let filter='all';const search=document.getElementById('search');function apply(){let visible=0;document.querySelectorAll('tr[data-status]').forEach(row=>{row.hidden=(filter==='pending'&&row.dataset.status==='ok')||(search.value&&!row.textContent.toLowerCase().includes(search.value.toLowerCase()));if(!row.hidden)visible++});document.getElementById('no-results').style.display=visible?'none':'block'}
if(search)search.oninput=apply;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n===b));apply()});
document.querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{const row=b.closest('tr');document.getElementById('row-title').textContent=b.dataset.row+' · 条目详情';document.getElementById('row-model').textContent=row.children[1].textContent;document.getElementById('row-qty').textContent=row.children[2].textContent;const c=document.getElementById('candidate');c.disabled=b.dataset.row!=='U1';c.selectedIndex=0;tell('已查看 '+b.dataset.row+' 的合成示例详情')});
